const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Nassau County, NY
  const nassau = ee.Geometry.Point([-73.5594, 40.7891]).buffer(20000); // 20km buffer

  // 2. Define time periods
  const periods = [
    {year: 2018, start: '2018-10-01', end: '2018-10-24'},
    {year: 2019, start: '2019-10-01', end: '2019-10-24'},
    {year: 2021, start: '2021-10-01', end: '2021-10-24'}
  ];

  // 3. Function to get NO2 data
  function getNO2(startDate, endDate) {
    return ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterDate(startDate, endDate)
      .filterBounds(nassau)
      .select('tropospheric_NO2_column_number_density');
  }

  const results = {};

  // 4. Process each period
  for (const period of periods) {
    const col = getNO2(period.start, period.end);
    const size = col.size().getInfo();

    if (size === 0) {
      console.log(`No images for ${period.year}`);
      console.log('<answer>C1</answer>');
      return;
    }

    // Calculate mean NO2
    const meanImg = col.mean();

    const stats = meanImg.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: nassau,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

    const meanVal = stats.tropospheric_NO2_column_number_density_mean;
    const count = stats.tropospheric_NO2_column_number_density_count;

    if (count === 0) {
      console.log(`No valid pixels for ${period.year}`);
      console.log('<answer>C2</answer>');
      return;
    }

    if (meanVal === null || meanVal === undefined || isNaN(meanVal)) {
      console.log(`Invalid calculation for ${period.year}`);
      console.log('<answer>C3</answer>');
      return;
    }

    results[period.year] = {mean: meanVal, count: count, images: size};
    console.log(`${period.year}: Images=${size}, Mean NO2=${meanVal.toExponential(3)}, Pixels=${count}`);
  }

  // 5. Compare 2021 with 2018 and 2019
  const lower2018 = results[2021].mean < results[2018].mean;
  const lower2019 = results[2021].mean < results[2019].mean;

  console.log(`2021 < 2018: ${lower2018}, 2021 < 2019: ${lower2019}`);

  if (lower2018 && lower2019) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
